449	
450	// writeAuthStatusLine writes one aligned "  Label   value" row of the
451	// `entire auth status` block. writeProfileLines and runAuthStatus both render
452	// into this same column, so the label width lives here in one place (it must be
453	// ≥ the longest label, currently "Jurisdiction:").
454	func writeAuthStatusLine(w io.Writer, label, value string) {
455		fmt.Fprintf(w, "  %-13s %s\n", label, value)
456	}
457	
458	// writeProfileLines renders the user identity from GET /me as aligned
459	// label/value lines, omitting any field the server didn't populate.
460	func writeProfileLines(w io.Writer, p *authProfile) {
461		var parts []string
462		if p.DisplayName != "" {
463			parts = append(parts, p.DisplayName)
464		}
465		if p.Handle != "" {
466			parts = append(parts, "@"+p.Handle)
467		}
468		if p.Email != "" {
469			parts = append(parts, "<"+p.Email+">")
470		}
471		if len(parts) > 0 {
472			writeAuthStatusLine(w, "User:", strings.Join(parts, " "))
473		}
474		if p.Provider != "" {
475			identity := p.Provider
476			if p.ProviderUserID != "" {
477				identity += "/" + p.ProviderUserID
478			}
479			writeAuthStatusLine(w, "Identity:", identity)
