// JurisdictionHost returns the base URL of the named jurisdiction's
// console host (empty if unknown). Used by foreign-jurisdiction-aware
// handlers to compose deep links.
func (s *Server) JurisdictionHost(jurisdiction string) string {
	return s.jurisdictionHosts[jurisdiction]
}

// JurisdictionAPIHost returns the base URL of the named jurisdiction's
// entire-api (the cell-bound data API), or empty if unconfigured. Surfaced
// on GET /api/v1/clusters so a home-jurisdiction reader can address /me.
func (s *Server) JurisdictionAPIHost(jurisdiction string) string {
	return s.jurisdictionAPIHosts[jurisdiction]
}

// LookupRepoLocalOrGlobal exposes the regional → global registry repo
// lookup so coreapi can present unified GET /repos/{id} semantics.
// Returns (*model.Repo, jurisdiction string, isForeign bool, error).
// jurisdiction is the repo's home region — this core's own for a regional
// hit ("" on a jurisdiction-agnostic core), the registry's stamp for a
// foreign row — carried alongside because model.Repo deliberately has no
// jurisdiction field (a row's region is implied by whose store it came
// from). isForeign=true means only ID/OwningProjectID/Name/ClusterSlug
// are populated.
func (s *Server) LookupRepoLocalOrGlobal(ctx context.Context, repoID model.RepoID) (*model.Repo, string, bool, error) {
	return s.lookupRepoLocalOrGlobal(ctx, repoID)
}

// JurisdictionRedirect returns a *MirrorOpError carrying the 421 redirect to
// the resource's home core, or nil when the owning jurisdiction is local (or
// this core is jurisdiction-agnostic, i.e. global). Reuses the

