			// console SPA that was retired: a bare "/" now redirects by
			// role (handleConsoleRoot), so that link landed on the admin
			// bundle for a platform admin and the marketing site for
			// everyone else — never a profile. Every other console deep
			// link in this codebase is hash-routed under /admin.html, and
			// the admin SPA has no profile route either, so there is
			// nothing to point at. Emit the origin and let clients decide.
			HomeCoreURL: strings.TrimRight(base, "/"),
