package coreapi

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"entire.io/core/api"
	"entire.io/core/cluster"
	"entire.io/core/mirrorrepo/gitjobs"
	"entire.io/core/model"
	"entire.io/core/repoadmin"
)

// meRegional decodes the regional block of a GET /me response body.
func meRegional(t *testing.T, raw []byte) struct {
	Email string `json:"email"`
} {
	t.Helper()
	var body struct {
		Regional *struct {
			Email string `json:"email"`
		} `json:"regional"`
	}
	if err := json.Unmarshal(raw, &body); err != nil {
		t.Fatalf("decode /me body: %v; raw=%s", err, raw)
	}
	if body.Regional == nil {
		return struct {
			Email string `json:"email"`
		}{}
	}
	return *body.Regional
}

func TestGetMe_CreatedAt(t *testing.T) {
	h, identitySvc, _, _ := setupIdentityAPI(t)
	ctx := context.Background()
	acct, hdl, err := identitySvc.CreateAccountWithHandle(ctx, "us", "github",
		uniqName(t, "created"), uniqName(t, "gh-created"), true)
	if err != nil {
		t.Fatalf("seed account: %v", err)
	}

	req := httptest.NewRequestWithContext(api.ContextWithClaims(ctx, claimsFor(acct, hdl)),
		http.MethodGet, "/api/v1/me", nil)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("GET /me status = %d, body=%s", rec.Code, rec.Body.String())
	}

	var body struct {
		Global struct {
			CreatedAt time.Time `json:"createdAt"`
		} `json:"global"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode /me body: %v; raw=%s", err, rec.Body.String())
	}
	if body.Global.CreatedAt.IsZero() {
		t.Fatalf("createdAt is zero, want the account's creation time")
	}
	if !body.Global.CreatedAt.Equal(acct.CreatedAt) {
		t.Fatalf("createdAt = %s, want %s", body.Global.CreatedAt, acct.CreatedAt)
	}
}

// TestGetMe_ResolvedEmail_VerifiedPrimary confirms regional.email is the
// resolved, provider-derived contact email — the verified primary provider
// email, even though the user never set a contact email.
func TestGetMe_ResolvedEmail_VerifiedPrimary(t *testing.T) {
	h, identitySvc, regionalSvc, _ := setupIdentityAPI(t)
	ctx := context.Background()
