// resolves (only a noreply provider email, no handle email), regional.email is
// omitted and /me still returns 200.
func TestGetMe_ResolvedEmail_NoneOmitted(t *testing.T) {
	h, identitySvc, regionalSvc, _ := setupIdentityAPI(t)
	ctx := context.Background()
	acct, hdl, err := identitySvc.CreateAccountWithHandle(ctx, "us", "github",
		uniqName(t, "noreply"), uniqName(t, "gh-noreply"), true)
	if err != nil {
		t.Fatalf("seed account: %v", err)
	}
	noreply := "12345+octocat@users.noreply.github.com"
	if err := regionalSvc.ReplaceProviderEmails(ctx, acct.ID, "github", []model.ProviderEmail{
		{Email: noreply, IsPrimary: true, Verified: true},
	}); err != nil {
