		t.Fatalf("createdAt is zero, want the account's creation time")
	}
	if !body.Global.CreatedAt.Equal(acct.CreatedAt) {
		t.Fatalf("createdAt = %s, want %s", body.Global.CreatedAt, acct.CreatedAt)
	}
}

// TestGetMe_ResolvedEmail_VerifiedPrimary confirms regional.email is the
// resolved, provider-derived contact email — the verified primary provider
// email, even though the user never set a contact email.
func TestGetMe_ResolvedEmail_VerifiedPrimary(t *testing.T) {
