	}
	if err := regionalSvc.ReplaceProviderEmails(ctx, acct.ID, "github", []model.ProviderEmail{
		{Email: "secondary@example.com", IsPrimary: false, Verified: true},
		{Email: "primary@example.com", IsPrimary: true, Verified: true},
