// TestGetMe_ForeignAccount_NoEmailLeak is the CRITICAL PII-non-leak invariant:
// a regional-mode node serving a FOREIGN account must NOT run ResolveContactEmail
// (whose handle fallback reads the global identity service) — so the resolved
// contact email is not surfaced and regionalUnavailable is returned instead.
// (global.handles[].email — the provider's PUBLIC mirror — is a separate, always-
// present field and not what this guards.)
func TestGetMe_ForeignAccount_NoEmailLeak(t *testing.T) {
	_, identitySvc, regionalSvc, resourceSvc := setupIdentityAPI(t)
	ctx := context.Background()
	// Account home is "us"; seed a verified provider email that WOULD resolve
	// into regional.email on the home node.
	acct, hdl, err := identitySvc.CreateAccountWithHandle(ctx, "us", "github",
		uniqName(t, "foreign"), uniqName(t, "gh-foreign"), true)
	if err != nil {
		t.Fatalf("seed account: %v", err)
	}
	if err := regionalSvc.ReplaceProviderEmails(ctx, acct.ID, "github", []model.ProviderEmail{
		{Email: "verified@example.com", IsPrimary: true, Verified: true},
	}); err != nil {
		t.Fatalf("seed provider emails: %v", err)
	}

	// A node in the "eu" jurisdiction — foreign to this "us"-home account.
	foreign := NewHandler(api.NewServer(api.Config{
		Jurisdiction: "eu",
		Identity:     identitySvc,
		Resource:     resourceSvc,
		JurisdictionCaps: &api.JurisdictionCapabilities{
			Regional:   regionalSvc,
			Resource:   resourceSvc,
			Cluster:    cluster.NewStore(coreapiPool(t)),
			Bridge:     repoadmin.NewRouter(nil),
			GitJobsPub: &gitjobs.Publisher{},
		},
		IdpCaps:           &api.IdpCapabilities{},
		JurisdictionHosts: map[string]string{"us": "https://us.console.example"},
		AuthBaseURL:       "https://test.auth.partial.to",
		ConsoleURL:        "https://test.auth.partial.to",
	}))

	rec := getMeRec(t, foreign, acct, hdl)
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, body=%s", rec.Code, rec.Body.String())
	}
	// No resolved contact email leaked from the foreign node: regional is absent
	// and the verified provider email (the private contact source) is nowhere in
	// the body.
	if got := meRegional(t, rec.Body.Bytes()).Email; got != "" {
		t.Fatalf("regional.email = %q, want empty on a foreign node", got)
	}
	if b := rec.Body.String(); strings.Contains(b, "verified@example.com") {
		t.Fatalf("verified provider email leaked from foreign node: %s", b)
	}
	// The foreign node names the caller's home jurisdiction instead.
	var body struct {
		RegionalUnavailable *struct {
			Error        string `json:"error"`
			Jurisdiction string `json:"jurisdiction"`
			HomeCoreURL  string `json:"homeCoreUrl"`
			Message      string `json:"message"`
		} `json:"regionalUnavailable"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode /me body: %v", err)
	}
	if body.RegionalUnavailable == nil || body.RegionalUnavailable.Error != "foreign_jurisdiction" {
		t.Fatalf("want regionalUnavailable.error=foreign_jurisdiction, got %+v; body=%s", body.RegionalUnavailable, rec.Body.String())
	}
	ru := body.RegionalUnavailable
	if ru.Jurisdiction != "us" {
		t.Errorf("regionalUnavailable.jurisdiction = %q, want us (the account's home)", ru.Jurisdiction)
	}
	// homeCoreUrl is the home console's bare origin. It must not carry the old
	// "/#/profile" fragment, which pointed at the retired user-facing console
	// SPA: a bare "/" redirects by role, so that link resolved to the admin
	// bundle or the marketing site, never a profile page.
	if ru.HomeCoreURL != "https://us.console.example" {
		t.Errorf("regionalUnavailable.homeCoreUrl = %q, want the bare home console origin", ru.HomeCoreURL)
	}
	// Nor may the copy tell the user to go open a page that doesn't exist.
	if strings.Contains(ru.Message, "Open it on") {
		t.Errorf("regionalUnavailable.message = %q, must not promise an openable profile page", ru.Message)
	}
	if !strings.Contains(ru.Message, "us jurisdiction") {
		t.Errorf("regionalUnavailable.message = %q, want the home jurisdiction named", ru.Message)
	}
}

// getMeRec issues an authenticated GET /api/v1/me and returns the recorder.
func getMeRec(t *testing.T, h http.Handler, acct *model.Account, hdl *model.Handle) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequestWithContext(api.ContextWithClaims(context.Background(), claimsFor(acct, hdl)),
		http.MethodGet, "/api/v1/me", nil)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

