// JurisdictionAuthHost returns the named jurisdiction's core origin — its OIDC
// issuer URL, e.g. "https://us.auth.entire.io" — or empty if unconfigured.
// This is the origin a token from that jurisdiction carries as `iss`, and the
// one the 421 cross-jurisdiction redirect hands clients as `home_core_url`.
//
// Distinct from JurisdictionHost, which is the console (a browser surface).
// Prefer this whenever the value is meant for a client to address.
func (s *Server) JurisdictionAuthHost(jurisdiction string) string {
	return s.jurisdictionAuthHosts[jurisdiction]
}

