		HomeCoreURL:  strings.TrimRight(s.Server.JurisdictionAuthHost(acct.HomeJurisdiction), "/"),
		Message:      fmt.Sprintf("Your profile is hosted in the %s jurisdiction.", acct.HomeJurisdiction),
	}
}

