// The foreign_jurisdiction discriminator is about where the account lives, not
// about console configuration: it must still be emitted on a node that has no
// jurisdiction hosts configured at all. This used to be gated on a console
// host being present, which silently collapsed "hosted elsewhere" into the
// same empty-regional shape as "no profile yet".
func TestGetMe_ForeignJurisdictionWithoutConsoleHosts(t *testing.T) {
	_, identitySvc, regionalSvc, resourceSvc := setupIdentityAPI(t)
	acct, hdl, err := identitySvc.CreateAccountWithHandle(context.Background(), "us", "github",
		uniqName(t, "noconsole"), uniqName(t, "gh-noconsole"), true)
	if err != nil {
		t.Fatalf("seed account: %v", err)
	}

	foreign := NewHandler(api.NewServer(api.Config{
		Jurisdiction: "eu",
		Identity:     identitySvc,
		Resource:     resourceSvc,
		JurisdictionCaps: &api.JurisdictionCapabilities{
			Regional:   regionalSvc,
			Resource:   resourceSvc,
			Cluster:    cluster.NewStore(coreapiPool(t)),
			Bridge:     repoadmin.NewRouter(nil),
			GitJobsPub: &gitjobs.Publisher{},
		},
		IdpCaps: &api.IdpCapabilities{},
		// No JurisdictionHosts at all.
		AuthBaseURL: "https://test.auth.partial.to",
		ConsoleURL:  "https://test.auth.partial.to",
	}))

	rec := getMeRec(t, foreign, acct, hdl)
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, body=%s", rec.Code, rec.Body.String())
	}
	var body struct {
		RegionalUnavailable *struct {
			Error        string `json:"error"`
			Jurisdiction string `json:"jurisdiction"`
		} `json:"regionalUnavailable"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode /me body: %v", err)
	}
	if body.RegionalUnavailable == nil {
		t.Fatalf("regionalUnavailable absent with no console hosts configured; body=%s", rec.Body.String())
	}
	if body.RegionalUnavailable.Error != "foreign_jurisdiction" || body.RegionalUnavailable.Jurisdiction != "us" {
		t.Errorf("regionalUnavailable = %+v, want foreign_jurisdiction/us", body.RegionalUnavailable)

